// Types for the inventory optimization data bundle, generated by
// src/export_json.py from the Python pipeline's CSV outputs. Field names
// match the exported JSON exactly (snake_case, matching the CSVs) so no
// mapping layer is needed between the pipeline and the frontend.

export interface SimulationSummary {
  n_skus: number;
  n_days_simulated: number;
  total_stockout_days_naive: number;
  total_stockout_days_optimized: number;
  stockout_days_avoided: number;
  pct_stockout_reduction: number;
  avg_service_level_naive: number;
  avg_service_level_optimized: number;
  total_holding_cost_naive: number;
  total_holding_cost_optimized: number;
  total_holding_cost_delta: number;
  pct_holding_cost_change: number;
  est_lost_sales_avoided_value: number;
  net_dollar_impact: number;
}

export interface SensitivityPoint {
  service_level_target: number;
  total_stockout_days: number;
  total_holding_cost: number;
  est_lost_sales_value: number;
  total_cost_of_policy: number;
}

export type AbcClass = "A" | "B" | "C";
export type XyzClass = "X" | "Y" | "Z";
export type AlertStatus = "RED" | "YELLOW" | "GREEN";

export interface PolicyRow {
  sku_id: string;
  category: string;
  sub_category: string;
  market: string;
  abc_class: AbcClass;
  service_level: number;
  z_score: number;
  lead_time_days: number;
  avg_daily_demand: number;
  std_daily_demand: number;
  safety_stock: number;
  reorder_point: number;
  eoq: number;
  orders_per_year: number;
  annual_holding_cost: number;
  annual_ordering_cost: number;
  annual_inventory_cost: number;
}

export interface AlertRow {
  sku_id: string;
  category: string;
  market: string;
  abc_class: AbcClass;
  status: AlertStatus;
  stock_on_hand: number;
  reorder_point: number;
  days_of_cover: number | null;
  units_below_reorder_point: number;
  suggested_order_qty: number;
  eoq: number;
  lead_time_days: number;
}

export interface SimulationResultRow {
  sku_id: string;
  category: string;
  market: string;
  abc_class: AbcClass;
  naive_stockout_days: number;
  optimized_stockout_days: number;
  stockout_days_avoided: number;
  naive_service_level_achieved: number;
  optimized_service_level_achieved: number;
  naive_avg_stock: number;
  optimized_avg_stock: number;
  naive_annual_holding_cost: number;
  optimized_annual_holding_cost: number;
  holding_cost_delta: number;
  est_lost_sales_avoided_value: number;
  net_dollar_impact: number;
}

export interface AbcRow {
  sku_id: string;
  revenue: number;
  cum_pct: number;
  revenue_share: number;
  abc_class: AbcClass;
  category: string;
  sub_category: string;
  market: string;
}

export interface VariabilityRow {
  sku_id: string;
  mean: number;
  std: number;
  cv: number;
  weekly_mean: number;
  weekly_std: number;
  zero_day_share: number;
  xyz_class: XyzClass;
  category: string;
  sub_category: string;
  market: string;
}

export interface SegmentationDetailRow {
  sku_id: string;
  abc_class: AbcClass;
  revenue: number;
  xyz_class: XyzClass;
  cv: number;
  zero_day_share: number;
  segment: string;
  recommended_approach: string;
}

export interface SegmentationSummaryRow {
  segment: string;
  n_skus: number;
  revenue: number;
  recommended_approach: string;
}

export interface Segmentation {
  detail: SegmentationDetailRow[];
  summary: SegmentationSummaryRow[];
}

export interface ForecastAccuracyRow {
  sku_id: string;
  best_model: "moving_average" | "holt_winters" | "croston";
  best_mae: number;
  best_mape: number;
  moving_average_mae?: number;
  moving_average_mape?: number;
  holt_winters_mae?: number;
  holt_winters_mape?: number;
  croston_mae?: number;
  croston_mape?: number;
}

export interface ForecastVsActualPoint {
  date: string;
  actual: number;
  forecast: number;
  model: string;
}

export type ForecastVsActual = Record<string, ForecastVsActualPoint[]>;

export interface GeographyRow {
  Country: string;
  revenue: number;
  profit: number;
  units: number;
  margin_pct: number;
}

export interface SkuDimRow {
  sku_id: string;
  category: string;
  sub_category: string;
  market: string;
  unit_cost: number;
  unit_price: number;
  lead_time_days: number;
  order_cost: number;
  holding_cost_pct: number;
}
